SELECT     ril.ITEM                                    AS ITEM_NUMBER,     im.ITEM_DESC                                AS item_description,     im.DEPT                                     AS department,     d.DEPT_NAME                                 AS department_name,     ril.LOCATION                                AS location,     ril.LOC_TYPE                                AS location_type,     COALESCE(st.STORE_NAME, wh.WH_NAME)         AS location_name,     ril.REPL_METHOD                             AS replenishment_method,     ril.LAST_ROQ                                AS last_roq,     ril.MIN_STOCK                               AS min_stock,     ril.MAX_STOCK                               AS max_stock,      oh.ORDER_NO                                 AS order_number,     oh.ORDER_TYPE                               AS order_type,     oh.STATUS                                   AS po_status,     oh.WRITTEN_DATE                             AS po_written_date,     oh.NOT_BEFORE_DATE                          AS not_before_date,     oh.NOT_AFTER_DATE                           AS not_after_date,     oh.ORIG_APPROVAL_DATE                       AS approval_date,     oh.SUPPLIER                                 AS supplier_number,     su.SUP_NAME                                 AS supplier_name,      ol.QTY_ORDERED                              AS qty_ordered,     ol.QTY_RECEIVED                             AS qty_received,     ol.QTY_CANCELLED                            AS qty_cancelled,     ol.UNIT_COST                                AS unit_cost,     ol.UNIT_RETAIL                              AS unit_retail,     ol.ESTIMATED_INSTOCK_DATE                   AS estimated_instock_date,      TRUNC(SYSDATE) - TRUNC(oh.WRITTEN_DATE)     AS days_since_order  FROM     MFCS_RDS.RDS_WV_REPL_ITEM_LOC              ril      JOIN MFCS_RDS.RDS_WV_ITEM_MASTER            im         ON  im.ITEM             = ril.ITEM      LEFT JOIN MFCS_RDS.RDS_WV_DEPS              d         ON  d.DEPT              = im.DEPT         LEFT JOIN MFCS_RDS.RDS_WV_ORDLOC            ol         ON  ol.ITEM             = ril.ITEM         AND ol.LOCATION         = ril.LOCATION      LEFT JOIN MFCS_RDS.RDS_WV_ORDHEAD           oh         ON  oh.ORDER_NO         = ol.ORDER_NO         AND oh.ORDER_TYPE       IN ('ARB', 'BRB')               LEFT JOIN MFCS_RDS.RDS_WV_SUPS              su         ON  su.SUPPLIER         = oh.SUPPLIER      LEFT JOIN MFCS_RDS.RDS_WV_STORE             st         ON  st.STORE            = ril.LOCATION         AND ril.LOC_TYPE        = 'S'      LEFT JOIN MFCS_RDS.RDS_WV_WH               wh         ON  wh.WH               = ril.LOCATION         AND ril.LOC_TYPE        = 'W'  WHERE     ril.STATUS                  = 'A'     AND ril.LAST_ROQ            &gt; 0     AND oh.ORDER_TYPE       IN ('ARB', 'BRB')  ORDER BY     ril.LAST_ROQ                DESC,     oh.WRITTEN_DATE             DESC,     ril.LOCATION,     im.DEPT,     ril.ITEM</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>ITEM_NUMBER</ds:name><ds:datatype>varchar(25)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>ITEM_DESCRIPTION</ds:name><ds:datatype>varchar(250)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>DEPARTMENT</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>DEPARTMENT_NAME</ds:name><ds:datatype>varchar(120)</ds:datatype></ds:column><ds:column><ds:name>LOCATION</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>LOCATION_TYPE</ds:name><ds:datatype>varchar(6)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>LOCATION_NAME</ds:name><ds:datatype>varchar(150)</ds:datatype></ds:column><ds:column><ds:name>REPLENISHMENT_METHOD</ds:name><ds:datatype>varchar(6)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds